import numpy as np,pandas as pd
from scipy.spatial.distance import cdist
z=np.load('/tmp/steel_more.npz');t=pd.read_csv('/work/b3_htsteel_toughness_pareto_train.csv');pool=pd.read_csv('/work/b3_htsteel_toughness_pareto_pool.csv');ids=pool.candidate_id.values;Y=z['Y'];rng=np.random.default_rng(91)
ns=['cat4','cat6','et','rf','gb','catfeat4','catfeat6']
P=np.array([z['p_'+n] for n in ns]);O=np.array([z['o_'+n] for n in ns]);mean=P.mean(axis=0);err=Y-O.mean(axis=0)
X=t.iloc[:,:-2].copy();Q=pool[X.columns].copy()
for c in X.columns:
 if 'time' in c or 'cooling rate' in c: X[c]=np.log1p(X[c]);Q[c]=np.log1p(Q[c])
s=X.std().values;s=np.maximum(s,.001)
for i,c in enumerate(X.columns):
 if 'temperature' in c:s[i]=max(s[i],150)
 if 'time' in c:s[i]=max(s[i],1.5)
D=cdist(Q.values/s,X.values/s,metric='cityblock');Dt=cdist(X.values/s,X.values/s,metric='cityblock');np.fill_diagonal(Dt,np.inf)
NN=np.argsort(D,axis=1)[:,:20]
num=5000
samples=np.empty((num,100,2)); choices=rng.integers(len(ns),size=num)
for i in range(100):
 nn=NN[i];w=1/(D[i,nn]+.5)**2;w/=w.sum();ee=err[nn];mu=np.average(ee,weights=w,axis=0);res=ee[rng.choice(20,num,p=w)]-mu
 # Only moderate residual shrinkage for candidates much closer to observed points than held-out training points.
 fac=np.clip((D[i,nn[0]]+.2)/(Dt[nn[0]].min()+.2),.35,1.5)
 samples[:,i]=P[choices,i]+.75*fac*res
samples=np.maximum(samples,[177,2])

def hv(a,ref=(177,2)):
 a=np.maximum(a-np.array(ref),0);inds=np.argsort(a[:,:,0],axis=1);x=np.take_along_axis(a[:,:,0],inds,axis=1);yy=np.take_along_axis(a[:,:,1],inds,axis=1);my=np.maximum.accumulate(yy[:,::-1],axis=1)[:,::-1];return np.sum(np.diff(x,prepend=0,axis=1)*my,axis=1).mean()

def opt(s):
 sel=[]
 for j in range(5):
  scores=np.array([hv(s[:,sel+[i]]) if i not in sel else -np.inf for i in range(100)]);n=scores.argmax();sel.append(n);print('greedy',j,ids[n],scores[n])
 for it in range(5):
  best=hv(s[:,sel]);found=None
  for j in range(5):
   for i in range(100):
    if i in sel:continue
    ss=sel.copy();ss[j]=i;v=hv(s[:,ss])
    if v>best+1e-5:best=v;found=ss
  if found is None:break
  sel=found
 print('SELECTED',ids[sel],hv(s[:,sel]));return sel
print('MEAN');opt(mean[None])
print('MODEL MIXTURE');opt(P)
print('UNCERTAINTY');ss=opt(samples)
for i in np.unique(np.r_[ss,[4,10,14,33,37,41,49,52,72,85]]): print(ids[i],np.round(mean[i],1),'uncert',np.round(np.std(samples[:,i],axis=0),1),'nearest',int(NN[i,0]),round(D[i,NN[i,0]],2))

